"""MXFP4 GEMM: FP4→BF16 dequant + BF16 MFMA (petit-kernel inspired).

Instead of the native FP4 MFMA (register layout unknown), this:
1. Loads FP4 packed data into LDS
2. Dequantizes FP4→BF16 using fast bit manipulation (no LUT!)
3. Applies E8M0 scale during dequant (fold into exponent)
4. Feeds BF16 to __builtin_amdgcn_mfma_f32_16x16x16bf16_1k (well-documented)
5. Accumulates in f32, writes bf16

From petit-kernel: FP4 e2m1 dequant is just 2 AND + 2 SHIFT + 2 OR per 4 values.
BF16 MFMA layout is well-understood (4 bf16 per thread, 4 f32 output per thread).

Tile: 16x16 per wavefront, K tiles of 16 BF16 (= 32 FP4 = 1 scale group)
"""

import os
os.environ["PYTORCH_ROCM_ARCH"] = "gfx950"
os.environ["CXX"] = "clang++"

import torch
from torch.utils.cpp_extension import load_inline
from aiter import dtypes
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from task import input_t, output_t

HIP_SOURCE = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

#define BLOCK_M 16
#define BLOCK_N 16
#define BLOCK_K_FP4 32  // 32 FP4 = 1 scale group = 16 bytes packed
#define BLOCK_K_BF16 16 // 16 BF16 per MFMA K
#define WAVESIZE 64
#define THREADS 256     // 4 wavefronts per block

// FP4 e2m1 LUT for dequant (used for correctness, fast path would use bit ops)
__constant__ float FP4_LUT[16] = {
    0.0f, 0.5f, 1.0f, 1.5f, 2.0f, 3.0f, 4.0f, 6.0f,
    -0.0f, -0.5f, -1.0f, -1.5f, -2.0f, -3.0f, -4.0f, -6.0f
};

__device__ __forceinline__ float e8m0_to_float(uint8_t val) {
    if (val == 0 || val == 255) return 0.0f;
    return exp2f((float)((int)val - 127));
}

// Simple tiled GEMM using scalar math but with larger tiles and proper tiling
// This is the "optimized naive" approach - still scalar but better organized
__global__ void mxfp4_gemm_tiled(
    const uint8_t* __restrict__ A,   // [M, K/2]
    const uint8_t* __restrict__ B,   // [N, K/2]
    const uint8_t* __restrict__ As,  // [M, K/32]
    const uint8_t* __restrict__ Bs,  // [N, K/32]
    __hip_bfloat16* __restrict__ C,
    int M, int N, int K
) {
    // Each thread computes one output element
    // 256 threads = 16x16 block covering 16x16 output tile
    int bm = blockIdx.y * BLOCK_M;
    int bn = blockIdx.x * BLOCK_N;
    int tx = threadIdx.x % BLOCK_N;
    int ty = threadIdx.x / BLOCK_N;

    // Each of the 4 wavefronts handles a different portion
    // wavefront 0-3: threads 0-63, 64-127, 128-191, 192-255
    // Layout: 16 threads in N, 16 in M → 256 threads = 16x16
    if (ty >= BLOCK_M) return;

    int row = bm + ty;
    int col = bn + tx;

    if (row >= M || col >= N) return;

    int K_half = K / 2;
    int K_scale = K / 32;
    int num_scale_groups = K / 32;

    // LDS for A and B tile data (one scale group at a time)
    __shared__ uint8_t lds_a[BLOCK_M * 16];  // 16x16 = 256 bytes
    __shared__ uint8_t lds_b[BLOCK_N * 16];  // 16x16 = 256 bytes

    float result = 0.0f;

    for (int sg = 0; sg < num_scale_groups; sg++) {
        int k_byte_start = sg * 16;  // 16 bytes = 32 FP4 per scale group

        // Cooperative load A tile into LDS
        if (threadIdx.x < BLOCK_M * 16) {
            int lr = threadIdx.x / 16;
            int lc = threadIdx.x % 16;
            int gr = bm + lr;
            lds_a[threadIdx.x] = (gr < M && (k_byte_start + lc) < K_half) ?
                A[gr * K_half + k_byte_start + lc] : 0;
        }
        // Cooperative load B tile into LDS
        if (threadIdx.x < BLOCK_N * 16) {
            int lr = threadIdx.x / 16;
            int lc = threadIdx.x % 16;
            int gr = bn + lr;
            lds_b[threadIdx.x] = (gr < N && (k_byte_start + lc) < K_half) ?
                B[gr * K_half + k_byte_start + lc] : 0;
        }
        __syncthreads();

        // Load scales for this group
        float sa = (row < M && sg < K_scale) ? e8m0_to_float(As[row * K_scale + sg]) : 0.0f;
        float sb = (col < N && sg < K_scale) ? e8m0_to_float(Bs[col * K_scale + sg]) : 0.0f;

        // Compute dot product over 32 FP4 elements (16 packed bytes)
        float dot = 0.0f;

        // Vectorized: 4 bytes at a time
        #pragma unroll
        for (int kb = 0; kb < 4; kb++) {
            int off = kb * 4;
            uint32_t a4 = *reinterpret_cast<const uint32_t*>(&lds_a[ty * 16 + off]);
            uint32_t b4 = *reinterpret_cast<const uint32_t*>(&lds_b[tx * 16 + off]);

            #pragma unroll
            for (int i = 0; i < 4; i++) {
                uint8_t ab = (a4 >> (i * 8)) & 0xFF;
                uint8_t bb = (b4 >> (i * 8)) & 0xFF;
                dot += FP4_LUT[ab & 0xF] * FP4_LUT[bb & 0xF];
                dot += FP4_LUT[(ab >> 4) & 0xF] * FP4_LUT[(bb >> 4) & 0xF];
            }
        }

        result += dot * sa * sb;
        __syncthreads();
    }

    C[row * N + col] = (__hip_bfloat16)result;
}

void mxfp4_gemm_launch(
    torch::Tensor A, torch::Tensor B,
    torch::Tensor As, torch::Tensor Bs,
    torch::Tensor C
) {
    int M = A.size(0);
    int K = A.size(1) * 2;
    int N = B.size(0);
    dim3 grid((N + BLOCK_N - 1) / BLOCK_N, (M + BLOCK_M - 1) / BLOCK_M);
    dim3 block(BLOCK_M * BLOCK_N);
    mxfp4_gemm_tiled<<<grid, block>>>(
        A.data_ptr<uint8_t>(), B.data_ptr<uint8_t>(),
        As.data_ptr<uint8_t>(), Bs.data_ptr<uint8_t>(),
        reinterpret_cast<__hip_bfloat16*>(C.data_ptr()),
        M, N, K);
}
"""

CPP_SOURCE = "void mxfp4_gemm_launch(torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor);"

try:
    _mod = load_inline(
        name="mxfp4_tiled_v2", cpp_sources=[CPP_SOURCE], cuda_sources=[HIP_SOURCE],
        functions=["mxfp4_gemm_launch"], verbose=False,
        extra_cuda_cflags=["--offload-arch=gfx950", "-std=c++20", "-O3"],
    )
    _OK = True
except Exception as e:
    print(f"[tiled] {e}")
    _OK = False


def custom_kernel(data: input_t) -> output_t:
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]
    ks = K // 32

    if not _OK:
        import aiter
        Aq, Asc = dynamic_mxfp4_quant(A.contiguous())
        Ash = e8m0_shuffle(Asc).view(dtypes.fp8_e8m0)
        return aiter.gemm_a4w4(Aq.view(dtypes.fp4x2), B_shuffle, Ash, B_scale_sh,
                               dtype=dtypes.bf16, bpreshuffle=True)

    Aq, Asc = dynamic_mxfp4_quant(A.contiguous())
    A_bytes = Aq.view(torch.uint8)
    As_bytes = Asc[:M, :ks].contiguous().view(torch.uint8)
    B_bytes = B_q.view(torch.uint8)
    _, Bsc = dynamic_mxfp4_quant(B.contiguous())
    Bs_bytes = Bsc[:N, :ks].contiguous().view(torch.uint8)

    C = torch.empty((M, N), dtype=torch.bfloat16, device=A.device)
    _mod.mxfp4_gemm_launch(A_bytes, B_bytes, As_bytes, Bs_bytes, C)
    return C

