"""MXFP4 GEMM with hardware MFMA intrinsic on gfx950.

Uses __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4 (CDNA4 only).
Single hardware instruction does dequant+matmul for FP4, replacing scalar LUT.

1 wavefront (64 threads) per 32x32 tile. Per-thread E8M0 scales.
Source: https://rocm.blogs.amd.com/software-tools-optimization/matrix-cores-cdna/README.html
"""

import os
os.environ["PYTORCH_ROCM_ARCH"] = "gfx950"
os.environ["CXX"] = "clang++"

import torch
from torch.utils.cpp_extension import load_inline
from aiter import dtypes
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from task import input_t, output_t

HIP_SOURCE = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

using fp4x2_t = uint8_t;
typedef fp4x2_t fp4x64_t __attribute__((ext_vector_type(32)));
typedef float fp32x16_t __attribute__((ext_vector_type(16)));

#define TILE_M 32
#define TILE_N 32
#define TILE_K 64
#define TILE_K_BYTES 32
#define WAVESIZE 64

// Stage data into LDS in contiguous 32x32 byte layout so we can use
// the blog's EXACT loading pattern for MFMA register packing.
__global__ void mxfp4_gemm_mfma(
    const uint8_t* __restrict__ A,   // [M, K/2]
    const uint8_t* __restrict__ B,   // [N, K/2]
    const uint8_t* __restrict__ As,  // [M, K/32]
    const uint8_t* __restrict__ Bs,  // [N, K/32]
    __hip_bfloat16* __restrict__ C,
    int M, int N, int K
) {
    int bm = blockIdx.y * TILE_M;
    int bn = blockIdx.x * TILE_N;
    int tid = threadIdx.x;

    int K_half = K / 2;
    int K_scale = K / 32;
    int num_k_tiles = K / TILE_K;

    // LDS: contiguous 32x32 byte blocks for A and B tiles
    // This matches the blog's flat array layout exactly
    __shared__ uint8_t lds_a[32 * 32];  // [32 rows][32 bytes] = 1024 bytes
    __shared__ uint8_t lds_b[32 * 32];  // [32 rows][32 bytes] = 1024 bytes

    fp32x16_t c_reg = {};
    for (int i = 0; i < 16; i++) c_reg[i] = 0.0f;

    for (int kt = 0; kt < num_k_tiles; kt++) {
        // ── Step 1: Cooperative load into LDS ──
        // 64 threads, 1024 bytes each = 16 bytes/thread
        for (int i = tid; i < 32 * 32; i += WAVESIZE) {
            int row = i / 32;
            int col = i % 32;
            int a_row = bm + row;
            int a_col = kt * TILE_K_BYTES + col;
            lds_a[i] = (a_row < M && a_col < K_half) ? A[a_row * K_half + a_col] : 0;
        }
        for (int i = tid; i < 32 * 32; i += WAVESIZE) {
            int row = i / 32;
            int col = i % 32;
            int b_row = bn + row;
            int b_col = kt * TILE_K_BYTES + col;
            lds_b[i] = (b_row < N && b_col < K_half) ? B[b_row * K_half + b_col] : 0;
        }
        __syncthreads();

        // ── Step 2: Read from LDS using blog's EXACT pattern ──
        fp4x64_t a_reg = {};
        fp4x64_t b_reg = {};

        // A: blog pattern — ldg_a = A + (t%32)*32 + (t/32)*16
        const uint8_t* ldg_a = lds_a + (tid % 32) * 32 + (tid / 32) * 16;
        for (int i = 0; i < 16; i++) {
            a_reg[i] = ldg_a[i];
        }

        // B: blog pattern — ldg_b = B + (t%32)/2 + 16*32*(t/32)
        const uint8_t* ldg_b = lds_b + (tid % 32) / 2 + 16 * 32 * (tid / 32);
        int b_extract_idx = tid % 2;
        for (int i = 0; i < 16; i++) {
            uint8_t by0 = *(ldg_b + 16 * 2 * i);
            uint8_t by1 = *(ldg_b + 16 * (2 * i + 1));
            uint8_t v0 = b_extract_idx ? ((by0 >> 4) & 0xF) : (by0 & 0xF);
            uint8_t v1 = b_extract_idx ? ((by1 >> 4) & 0xF) : (by1 & 0xF);
            b_reg[i] = v0 | (v1 << 4);
        }

        // ── Step 3: Scales ──
        int sg = kt * 2 + (tid / 32);  // scale group index
        int a_row = bm + (tid % 32);
        uint8_t sa = (a_row < M && sg < K_scale) ? As[a_row * K_scale + sg] : 127;
        // B scale: use first row of this thread's B-half as representative
        int b_rep = bn + 16 * (tid / 32);
        uint8_t sb = (b_rep < N && sg < K_scale) ? Bs[b_rep * K_scale + sg] : 127;

        // ── Step 4: MFMA ──
        c_reg = __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4(
            a_reg, b_reg, c_reg, 4, 4, 0, sa, 0, sb);

        __syncthreads();
    }

    // ── Step 5: Write output (blog's exact pattern) ──
    int out_col = bn + (tid % 32);
    if (out_col < N) {
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            int rb = bm + (tid / 32) * 4 + i * 8;
            #pragma unroll
            for (int j = 0; j < 4; j++) {
                int row = rb + j;
                if (row < M) C[row * N + out_col] = (__hip_bfloat16)(c_reg[i * 4 + j]);
            }
        }
    }
}

void mxfp4_gemm_launch(
    torch::Tensor A, torch::Tensor B,
    torch::Tensor As, torch::Tensor Bs,
    torch::Tensor C
) {
    int M = A.size(0);
    int K = A.size(1) * 2;
    int N = B.size(0);
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);
    dim3 block(WAVESIZE);
    mxfp4_gemm_mfma<<<grid, block>>>(
        A.data_ptr<uint8_t>(), B.data_ptr<uint8_t>(),
        As.data_ptr<uint8_t>(), Bs.data_ptr<uint8_t>(),
        reinterpret_cast<__hip_bfloat16*>(C.data_ptr()), M, N, K);
}
