// Packed 320-byte arg struct matching CK kernel ABI
#pragma pack(push, 1)
struct Args {
    void* ptr_R;       uint32_t _p0[2];
    void* ptr_LSE;     uint32_t _p1[2];
    void* ptr_Q;       uint32_t _p2[2];
    void* ptr_KV;      uint32_t _p3[2];
    void* ptr_LTP;     uint32_t _p4[2];
    void* ptr_LTD;     uint32_t _p5[2];
    void* ptr_LTL;     uint32_t _p6[2];
    float scalar;      uint32_t _p12[3];
    uint32_t s_MQA;    uint32_t _p13[3];
    uint32_t s_kv_split; uint32_t _p14[3];
    uint32_t s_Q_Bs;   uint32_t _p15[3];
    uint32_t s_Bs;     uint32_t _p16[3];
    uint32_t s_log2_plen; uint32_t _p17[3];
    void* ptr_QTP;     uint32_t _p18[2];
    void* ptr_STP;     uint32_t _p19[2];
    void* ptr_RP;      uint32_t _p20[2];
    void* ptr_QSCALE;  uint32_t _p21[2];
    void* ptr_KVSCALE; uint32_t _p22[2];
    uint32_t out_nosplit; uint32_t _p23[3];
    void* ptr_LSEP;    uint32_t _p24[2];
};
#pragma pack(pop)

int try_co_dispatch(
    torch::Tensor logits, torch::Tensor attn_lse,
    torch::Tensor q_fp8, torch::Tensor kv_4d,
    torch::Tensor kv_indptr, torch::Tensor kv_indices,
    torch::Tensor kv_last_len, torch::Tensor qo_indptr,
    torch::Tensor work_meta, torch::Tensor work_indptr,
    torch::Tensor output,
    torch::Tensor q_scale, torch::Tensor kv_scale,
    float sm_scale, int qseqlen, int num_splits, int gqa_ratio
) {
    if (!s_tried) {
        s_tried = true;
        if (hipModuleLoad(&s_mod, CO_PATH) != hipSuccess) return -1;
        if (hipModuleGetFunction(&s_func, s_mod, SYMBOL) != hipSuccess) return -2;
    }
    if (!s_func) return -3;

    Args args;
    memset(&args, 0, sizeof(args));
    args.ptr_R = logits.data_ptr();
    args.ptr_LSE = attn_lse.data_ptr();
    args.ptr_Q = q_fp8.data_ptr();
    args.ptr_KV = kv_4d.data_ptr();
