CPP_SOURCE = """
int try_co_dispatch(
    torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor,
    torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor,
    torch::Tensor, torch::Tensor, torch::Tensor,
    torch::Tensor, torch::Tensor,
    float, int, int, int);
"""

try:
    _mod = load_inline(
        name="mla_co_test", cpp_sources=[CPP_SOURCE], cuda_sources=[HIP_SOURCE],
        functions=["try_co_dispatch"], verbose=False,
        extra_cuda_cflags=["--offload-arch=gfx950", "-std=c++20", "-O3"],
    )
    _CO_OK = True
except Exception as e:
    print(f"[co_test] {e}")
    _CO_OK = False

_cache = {}

def _quantize_fp8(t):
    fi = torch.finfo(FP8_DTYPE)
    amax = t.abs().amax().clamp(min=1e-12)
    sc = amax / fi.max
    return (t / sc).clamp(fi.min, fi.max).to(FP8_DTYPE), sc.float().reshape(1)

def _choose_splits(total_kv):
    if total_kv <= 2048: return 4
    if total_kv <= 16384: return 8
    if total_kv <= 131072: return 16
    return 16

def _get_meta(bs, qsl, kvsl, qdt, kvdt, ns, qo, kvi):
    key = (bs, qsl, kvsl, qdt, kvdt, ns)
    if key in _cache: return _cache[key]
    nq, nkv = NUM_HEADS, NUM_KV_HEADS
    kvl = (kvi[1:] - kvi[:-1]).to(torch.int32)
    info = get_mla_metadata_info_v1(bs, qsl, nq, qdt, kvdt, is_sparse=False,
        fast_mode=False, num_kv_splits=ns, intra_batch_mode=True)
    work = [torch.empty(s, dtype=t, device="cuda") for s, t in info]
    wm, wi, wis, ri, rfm, rpm = work
    get_mla_metadata_v1(qo, kvi, kvl, nq//nkv, nkv, True, wm, wis, wi, ri, rfm, rpm,
        page_size=PAGE_SIZE, kv_granularity=16, max_seqlen_qo=qsl, uni_seqlen_qo=qsl,
        fast_mode=False, max_split_per_batch=ns, intra_batch_mode=True,
        dtype_q=qdt, dtype_kv=kvdt)
    tq = bs * qsl
    tkv = int(kvi[-1].item())
    buf = max(ns, 16)
    m = {"wm": wm, "wi": wi, "wis": wis, "ri": ri, "rfm": rfm, "rpm": rpm,
         "kvi": torch.arange(tkv, dtype=torch.int32, device="cuda"), "kvl": kvl,
         "logits": torch.empty((buf, tq, nq, V_HEAD_DIM), dtype=torch.float32, device="cuda"),
         "lse": torch.empty((buf, tq, nq), dtype=torch.float32, device="cuda"),
         "out": torch.empty((tq, nq, V_HEAD_DIM), dtype=torch.bfloat16, device="cuda")}
    _cache[key] = m
    return m

def custom_kernel(data: input_t) -> output_t:
    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    qsl = config["q_seq_len"]
    kvsl = config["kv_seq_len"]
    total_kv = bs * kvsl

    # Small shapes: einsum
    if bs <= MATMUL_MAX_BS or total_kv <= MATMUL_MAX_TOTAL_KV:
        kv = kv_data["bf16"].view(bs, kvsl, QK_HEAD_DIM)
        qr = q.view(bs, 1, NUM_HEADS, QK_HEAD_DIM)
        sc = torch.einsum("bqnh,bsh->bnqs", qr, kv).mul_(SM_SCALE)
        w = torch.softmax(sc, dim=-1)
        v = kv[:, :, :V_HEAD_DIM]
        return torch.einsum("bnqs,bsd->bqnd", w, v).reshape(-1, NUM_HEADS, V_HEAD_DIM).to(torch.bfloat16)

    # Large shapes: try .co dispatch, fallback to aiter
    kv_fp8, kv_scale = kv_data["fp8"]
    q_fp8, q_scale = _quantize_fp8(q)
    ns = _choose_splits(total_kv)
    kv_4d = kv_fp8.view(kv_fp8.shape[0], PAGE_SIZE, NUM_KV_HEADS, QK_HEAD_DIM)
    m = _get_meta(bs, qsl, kvsl, q_fp8.dtype, kv_fp8.dtype, ns, qo_indptr, kv_indptr)
    gqa = NUM_HEADS // NUM_KV_HEADS

    if _CO_OK:
        ret = _mod.try_co_dispatch(
            m["logits"], m["lse"], q_fp8.view(-1, NUM_HEADS, QK_HEAD_DIM),
            kv_4d, kv_indptr, m["kvi"], m["kvl"], qo_indptr,
            m["wm"], m["wi"], m["out"], q_scale, kv_scale,
            SM_SCALE, qsl, ns, gqa)
        if ret == 0:
            mla_reduce_v1(m["logits"], m["lse"], m["ri"], m["rfm"], m["rpm"], qsl, m["out"])
            return m["out"]

    # Fallback: standard aiter
    from aiter.mla import mla_decode_stage1_asm_fwd
    mla_decode_stage1_asm_fwd(
        q_fp8.view(-1, NUM_HEADS, QK_HEAD_DIM), kv_4d, qo_indptr, kv_indptr,
        m["kvi"], m["kvl"], None, m["wm"], m["wi"], m["wis"],
        qsl, PAGE_SIZE, NUM_KV_HEADS, SM_SCALE, m["logits"], m["lse"], m["out"],
        q_scale=q_scale, kv_scale=kv_scale)
    mla_reduce_v1(m["logits"], m["lse"], m["ri"], m["rfm"], m["rpm"], qsl, m["out"])
    return m["out"]

