            int tx = threadIdx.x % 16;  // 0-15 within compute wave
            int ty = (threadIdx.x >> 4) % 16;  // 0-15

            // Each thread computes 4x4 output tile
            for (int mi = 0; mi < 4; mi++) {
                int row_idx = ty * 4 + mi;
