                        float a1 = fp4_to_f32((a_byte >> 4) & 0xF);
                        float b0 = fp4_to_f32(b_byte & 0xF);
                        float b1 = fp4_to_f32((b_byte >> 4) & 0xF);

                        dot += a0 * b0 + a1 * b1;
                    }
